# Range and tails of the derivatives of every link, orders 1 to 6, both directions.
#
# Generated by misure_link6/make_tests.py. The reference values are mpmath
# (50 to 420 digits). `fixed` lists arguments where a derivative returned NaN,
# a premature infinity or zero, or a relative error above 1e-9 before the
# overflow and underflow work (cloglog and loglog inverse at large arguments,
# the Cauchit inverse past 1e77, the Probit inverse past 37, the logistic
# inverse past 710, the doubly bounded link near its upper bound and at widths
# of 1e-60 and 1e60, the rhobit near 1, the softplus tails, the monomial links
# past 1e51, the power link at whole-number exponents). `thr` lists, for each
# derivative that overflows, one argument 1e-6 inside the last finite
# argument and one 1e-6 beyond the first overflow, with the signed infinity
# expected there.

range6_links <- function() {
  list(
    `cauchit` = cauchit_link(),
    `cloglog` = cloglog_link(),
    `double_0_1` = bounded_link(lwr = 0, upr = 1),
    `double_0_1e-60` = bounded_link(lwr = 0, upr = 1e-60),
    `double_0_1e60` = bounded_link(lwr = 0, upr = 1e60),
    `double_2_5` = bounded_link(lwr = 2, upr = 5),
    `identity` = identity_link(),
    `inverse` = inverse_link(),
    `inverse_sq` = inverse_sq_link(),
    `log` = log_link(),
    `logit` = logit_link(),
    `loglog` = loglog_link(),
    `lower_0` = bounded_link(lwr = 0),
    `lower_2` = bounded_link(lwr = 2),
    `power_-0.5` = power_link(-0.5),
    `power_-1` = power_link(-1.0),
    `power_0.333333` = power_link(0.3333333333333333),
    `power_0.5` = power_link(0.5),
    `power_1.5` = power_link(1.5),
    `power_2` = power_link(2.0),
    `power_3` = power_link(3.0),
    `power_7` = power_link(7.0),
    `probit` = probit_link(),
    `rhobit` = rhobit_link(),
    `softplus_0.01` = softplus_link(0.01),
    `softplus_1` = softplus_link(1.0),
    `softplus_50` = softplus_link(50.0),
    `sqrt` = sqrt_link(),
    `upper_5` = bounded_link(upr = 5)

  )
}
range6_eval <- function(lk, dir, k, x) {
  gens <- if (dir == "fwd") list(dlinkfun, d2linkfun, d3linkfun, d4linkfun, d5linkfun, d6linkfun)
          else list(dlinkinv, d2linkinv, d3linkinv, d4linkinv, d5linkinv, d6linkinv)
  gens[[k]](lk, x)
}
range6_ok <- function(v, ref) {
  r <- if (ref == "Inf") Inf else if (ref == "-Inf") -Inf else as.numeric(ref)
  if (is.infinite(r)) return(identical(v, r))
  if (is.na(v) || is.infinite(v)) return(FALSE)
  abs(v - r) <= 1e-322 + 1e-11 * abs(r)
}

