test_that("derivatives at the former failure points match the high-precision reference", {
  links <- range6_links()
  for (i in seq_len(nrow(range6_fixed))) {
    f <- range6_fixed[i, ]
    v <- range6_eval(links[[f$inst]], f$dir, f$k, f$arg)
    expect_true(range6_ok(v, f$ref),
                label = sprintf("%s %s order %d at %s: got %s, reference %s", f$inst, f$dir, f$k,
                                format(f$arg, digits = 17), format(v, digits = 17), f$ref))
  }
})

test_that("each derivative is finite just inside its overflow point and infinite just beyond", {
  links <- range6_links()
  for (i in seq_len(nrow(range6_thr))) {
    f <- range6_thr[i, ]
    lk <- links[[f$inst]]
    vi <- range6_eval(lk, f$dir, f$k, f$inside)
    vo <- range6_eval(lk, f$dir, f$k, f$outside)
    expect_true(range6_ok(vi, f$ref_inside),
                label = sprintf("%s %s order %d inside (%s): got %s, reference %s", f$inst, f$dir, f$k,
                                format(f$inside, digits = 17), format(vi, digits = 17), f$ref_inside))
    expect_true(range6_ok(vo, f$ref_outside),
                label = sprintf("%s %s order %d beyond (%s): got %s, reference %s", f$inst, f$dir, f$k,
                                format(f$outside, digits = 17), format(vo, digits = 17), f$ref_outside))
  }
})
